SELECT CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END last_restock_cohort, MONTH(last_restock) last_restock_month, COUNT(quantity) quantity_count, ROUND(AVG(quantity), 2) avg_quantity FROM inventory WHERE NOT (product_id IN (2, 6) OR MONTH(last_restock) IN (2, 6, 9)) GROUP BY last_restock_cohort, last_restock_month HAVING MAX(quantity) < 190 ORDER BY quantity_count DESC;
